<script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../api/client';const items=ref<any[]>([]),resource=ref(''),actorID=ref('');async function load(){items.value=(await api.get('/audit-logs',{params:{page:1,page_size:100,resource:resource.value,actor_id:actorID.value}})).data.items||[]}onMounted(load)</script><template><div class="page"><div class="page-title"><div><h1>审计日志</h1><p>查询关键业务写入、资金操作和状态变化记录</p></div><button class="secondary-button" @click="load">刷新日志</button></div><section class="card"><div class="toolbar"><div class="toolbar-left"><div class="field"><input v-model="resource" class="search-input" placeholder="按资源类型筛选"></div><div class="field"><input v-model="actorID" class="search-input" placeholder="按操作者 ID 筛选"></div><button class="primary-button" @click="load">查询</button></div></div><table v-if="items.length" class="data-table"><thead><tr><th>操作时间</th><th>操作者</th><th>业务动作</th><th>资源</th><th>资源 ID</th><th>详情</th></tr></thead><tbody><tr v-for="x in items" :key="x.ID"><td>{{String(x.CreatedAt).replace('T',' ').slice(0,19)}}</td><td><code>{{x.ActorID?.slice(0,12)||'-'}}</code></td><td><span class="status-badge">{{x.Action}}</span></td><td>{{x.Resource}}</td><td><code>{{x.ResourceID?.slice(0,12)||'-'}}</code></td><td class="audit-detail">{{x.Detail}}</td></tr></tbody></table><div v-else class="empty-state"><b>暂无审计记录</b><span>新增、修改和资金操作完成后会自动记录</span></div></section></div></template><style scoped>.audit-detail{max-width:320px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}</style>